16	    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
17	        // First check if the number is zero
18	        //
19	        let number = BigUint::from_bytes_be(&self.to_be_bytes());
20	        if number == BigUint::zero() {
21	            return write!(f, "0");
22	        }
23	        // Check if the negative version is smaller to represent
24	        //
25	        let minus_number = BigUint::from_bytes_be(&(self.neg()).to_be_bytes());
26	        let (smaller_repr, is_negative) =
27	            if minus_number.to_string().len() < number.to_string().len() {
28	                (minus_number, true)
29	            } else {
30	                (number, false)
31	            };
32	        if is_negative {
33	            write!(f, "-")?;
34	        }
35	
36	        write!(f, "{smaller_repr}")
37	    }
38	}
