14	pub(crate) const DEFAULT_DOMAIN_SEPARATOR: &[u8] = "DEFAULT_DOMAIN_SEPARATOR".as_bytes();
15	const NUM_DEFAULT_GENERATORS: usize = 8;
16	
17	fn default_generators() -> &'static [Affine<GrumpkinParameters>; NUM_DEFAULT_GENERATORS] {
18	    static INSTANCE: OnceLock<[Affine<GrumpkinParameters>; NUM_DEFAULT_GENERATORS]> =
19	        OnceLock::new();
20	    INSTANCE.get_or_init(|| {
21	        _derive_generators(DEFAULT_DOMAIN_SEPARATOR, NUM_DEFAULT_GENERATORS as u32, 0)
22	            .try_into()
23	            .expect("Should generate `NUM_DEFAULT_GENERATORS`")
24	    })
