27	/// Derives generator points via [hash-to-curve][hash_to_curve].
28	///
29	/// # ALGORITHM DESCRIPTION
30	///
31	/// 1. Each generator has an associated "generator index" described by its location in the vector
32	/// 2. a 64-byte preimage buffer is generated with the following structure:
33	///     - bytes 0-31: BLAKE3 hash of domain_separator
34	///     - bytes 32-63: generator index in big-endian form
35	/// 3. The [hash-to-curve algorithm][hash_to_curve] is used to hash the above into a curve point.
36	///
37	/// NOTE: The domain separator is included to ensure that it is possible to derive independent sets of
38	/// index-addressable generators.
39	///
40	/// [hash_to_curve]: super::hash_to_curve::hash_to_curve
41	pub fn derive_generators(
42	    domain_separator_bytes: &[u8],
43	    num_generators: u32,
44	    starting_index: u32,
45	) -> Vec<Affine<GrumpkinParameters>> {
46	    // We cache a small number of the default generators so we can reuse them without needing to repeatedly recalculate them.
47	    if domain_separator_bytes == DEFAULT_DOMAIN_SEPARATOR
48	        && starting_index + num_generators <= NUM_DEFAULT_GENERATORS as u32
49	    {
50	        let start_index = starting_index as usize;
51	        let end_index = (starting_index + num_generators) as usize;
52	        default_generators()[start_index..end_index].to_vec()
53	    } else {
54	        _derive_generators(domain_separator_bytes, num_generators, starting_index)
55	    }
56	}
57	
58	fn _derive_generators(
59	    domain_separator_bytes: &[u8],
60	    num_generators: u32,
61	    starting_index: u32,
62	) -> Vec<Affine<GrumpkinParameters>> {
63	    let mut generator_preimage = [0u8; 64];
64	    let domain_hash = blake3(domain_separator_bytes).expect("hash should succeed");
65	    //1st 32 bytes are blake3 domain_hash
66	    generator_preimage[..32].copy_from_slice(&domain_hash);
67	
68	    // Convert generator index in big-endian form
69	    let mut res = Vec::with_capacity(num_generators as usize);
70	    for i in starting_index..(starting_index + num_generators) {
71	        let generator_be_bytes: [u8; 4] = i.to_be_bytes();
72	        generator_preimage[32] = generator_be_bytes[0];
73	        generator_preimage[33] = generator_be_bytes[1];
74	        generator_preimage[34] = generator_be_bytes[2];
75	        generator_preimage[35] = generator_be_bytes[3];
76	        let generator = hash_to_curve(&generator_preimage, 0);
77	        res.push(generator);
78	    }
79	    res
80	}
